"""Tensor-parallel linear layers (Megatron-style) implemented with PyTorch.

Only public APIs are used:
  * ``torch.distributed.is_available`` / ``is_initialized``
  * ``torch.distributed.get_world_size`` / ``get_rank``
  * ``torch.distributed.all_reduce`` / ``all_gather``
  * ``torch.nn`` and ``torch.autograd.Function``
"""

import torch
import torch.distributed as dist


# --------------------------------------------------------------------------- #
# helpers
# --------------------------------------------------------------------------- #
def _world_size():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size()
    return 1


def _rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank()
    return 0


def _all_reduce(tensor):
    """In-place sum across ranks (no-op when not running distributed)."""
    if _world_size() == 1:
        return tensor
    tensor = tensor.contiguous()
    dist.all_reduce(tensor)
    return tensor


def _all_gather_last_dim(tensor):
    """Gather ``tensor`` from every rank and concatenate along the last dim."""
    world_size = _world_size()
    if world_size == 1:
        return tensor
    tensor = tensor.contiguous()
    gathered = [torch.empty_like(tensor) for _ in range(world_size)]
    dist.all_gather(gathered, tensor)
    gathered[_rank()] = tensor  # keep autograd/data identity for local shard
    return torch.cat(gathered, dim=-1).contiguous()


class _CopyToModelParallelRegion(torch.autograd.Function):
    """Identity forward, all-reduce backward (the ``f`` operator)."""

    @staticmethod
    def forward(ctx, x):
        return x

    @staticmethod
    def backward(ctx, grad_output):
        return _all_reduce(grad_output.clone())


class _GatherFromModelParallelRegion(torch.autograd.Function):
    """All-gather forward (last dim), split backward (the ``g`` operator)."""

    @staticmethod
    def forward(ctx, x):
        ctx.local_size = x.shape[-1]
        return _all_gather_last_dim(x.detach() if x.requires_grad else x)

    @staticmethod
    def backward(ctx, grad_output):
        if _world_size() == 1:
            return grad_output
        chunks = torch.split(grad_output, ctx.local_size, dim=-1)
        return chunks[_rank()].contiguous()


class _ReduceFromModelParallelRegion(torch.autograd.Function):
    """All-reduce forward, identity backward (the ``g`` operator)."""

    @staticmethod
    def forward(ctx, x):
        return _all_reduce(x.clone())

    @staticmethod
    def backward(ctx, grad_output):
        return grad_output


def _shard(master_weight, out_features, in_features, dim):
    """Return this rank's contiguous slice of ``master_weight``.

    ``master_weight`` is expected with the ``torch.nn.Linear`` layout
    ``(out_features, in_features)``; the transposed layout is accepted too.
    ``dim`` is the dimension to split in the ``(out_features, in_features)``
    layout (0 -> column parallel, 1 -> row parallel).
    """
    weight = master_weight.detach()
    if tuple(weight.shape) == (out_features, in_features):
        pass
    elif tuple(weight.shape) == (in_features, out_features):
        weight = weight.t()
    else:
        raise ValueError(
            "master_weight has shape {} but ({}, {}) was expected".format(
                tuple(weight.shape), out_features, in_features
            )
        )

    world_size = _world_size()
    size = weight.shape[dim]
    if size % world_size != 0:
        raise ValueError(
            "dimension {} of size {} is not divisible by world size {}".format(
                dim, size, world_size
            )
        )
    per_rank = size // world_size
    start = _rank() * per_rank
    shard = weight.narrow(dim, start, per_rank)
    return shard.clone().contiguous()


# --------------------------------------------------------------------------- #
# layers
# --------------------------------------------------------------------------- #
class ColumnParallelLinear(torch.nn.Module):
    """Linear layer with the weight split along its output (column) dimension.

    ``Y = X A + b`` with ``A`` split column-wise as ``A = [A_1, ..., A_p]``.
    Each rank holds ``A_i`` (weight rows ``[i*out/p, (i+1)*out/p)``) and the
    matching bias slice; the outputs are concatenated along the last dimension
    (all_gather) so every rank returns the full result.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features

        world_size = _world_size()
        self.world_size = world_size
        self.rank = _rank()
        self.output_size_per_partition = out_features // world_size

        self.weight = torch.nn.Parameter(
            _shard(master_weight, out_features, in_features, dim=0)
        )

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(
                    self.output_size_per_partition,
                    dtype=self.weight.dtype,
                    device=self.weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, input_):
        # input is identical on every rank: identity forward, all-reduce backward
        input_parallel = _CopyToModelParallelRegion.apply(input_)
        output_parallel = torch.nn.functional.linear(
            input_parallel, self.weight, self.bias
        )
        return _GatherFromModelParallelRegion.apply(output_parallel)

    def extra_repr(self):
        return "in_features={}, out_features={}, bias={}".format(
            self.in_features, self.out_features, self.bias is not None
        )


class RowParallelLinear(torch.nn.Module):
    """Linear layer with the weight split along its input (row) dimension.

    ``Y = X A + b`` with ``A`` split row-wise and ``X`` already scattered along
    its last dimension, i.e. ``forward()`` receives only ``X_i``.  The partial
    products are summed across ranks (all_reduce) and the full bias is added
    afterwards, so every rank returns the full result.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features

        world_size = _world_size()
        self.world_size = world_size
        self.rank = _rank()
        self.input_size_per_partition = in_features // world_size

        self.weight = torch.nn.Parameter(
            _shard(master_weight, out_features, in_features, dim=1)
        )

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(
                    out_features,
                    dtype=self.weight.dtype,
                    device=self.weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, input_):
        # input_ is already this rank's slice along the last dimension
        output_parallel = torch.nn.functional.linear(input_, self.weight)
        output = _ReduceFromModelParallelRegion.apply(output_parallel)
        if self.bias is not None:
            output = output + self.bias
        return output

    def extra_repr(self):
        return "in_features={}, out_features={}, bias={}".format(
            self.in_features, self.out_features, self.bias is not None
        )
